def make_env(
    rank: int,
    seed: int,
    knobs: dict[str, Any],
    tiger_ai_mode: str | None = None,
    mix_prob: float | None = None,
    resolved_goat_ai: str | None = None,
    goat_model_path: str | None = None,
):
    def _init():
        def _sample_ai():
            if mix_prob is None:
                return tiger_ai_mode if tiger_ai_mode is not None else DEFAULT_TIGER_AI_MODE
            p = min(max(float(mix_prob), 0.0), 1.0)
            return TIGER_AI_SMART if random.random() < p else TIGER_AI_GREEDY

        def _sample_goat_ai():
            base_goat = resolved_goat_ai if resolved_goat_ai is not None else DEFAULT_GOAT_OPPONENT_AI
            if mix_prob is None or LEARNER_ROLE == GOAT_LEARNER:
                return base_goat
